var W = 1000, H = 780;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

// arrowhead marker
var mdef = draw.defs().marker(10, 10, function (add) { add.path('M0,0 L10,5 L0,10 z').fill('#c0392b'); });
mdef.attr({ orient: 'auto', markerWidth: 8, markerHeight: 8, refX: 8, refY: 5, id: 'arrHead' });

var gEdges = draw.group(), gArray = draw.group(), gNodes = draw.group(), gOver = draw.group();
var capText = draw.text('').attr({ x: W / 2, y: 735, 'text-anchor': 'middle', 'font-size': 15, 'font-family': 'sans-serif', fill: '#333', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });

var nodeX = [], nodeY = [], nodeCirc = [], nodeVal = [], nodeIdx = [];
var cellVal = [], cellRect = [];
var R = 27, TOP_Y = 175, GAP = 150, N = 0;

function computeLayout(n) {
  nodeX = [0]; nodeY = [0];
  for (var i = 1; i <= n; i++) {
    var L = Math.floor(Math.log2(i));
    var pos = i - Math.pow(2, L);
    var cnt = Math.pow(2, L);
    nodeX[i] = (pos + 0.5) * (W / cnt);
    nodeY[i] = TOP_Y + L * GAP;
  }
}

function parseArray() {
  var src = document.getElementById('maxHeapifyCodeInput').value;
  var parts = src.split(',').map(function (s) { return parseInt(s.trim(), 10); }).filter(function (v) { return isFinite(v); });
  if (!parts.length) parts = [4, 1, 3, 2, 16, 9, 10, 14, 8, 7];
  return parts;
}

function buildStructure(arr) {
  N = arr.length;
  computeLayout(N);
  gEdges.clear(); gArray.clear(); gNodes.clear(); gOver.clear();
  nodeCirc = [null]; nodeVal = [null]; nodeIdx = [null]; cellVal = [null]; cellRect = [null];
  // edges
  for (var i = 2; i <= N; i++) {
    var p = Math.floor(i / 2);
    gEdges.line(nodeX[p], nodeY[p], nodeX[i], nodeY[i]).stroke({ color: '#444', width: 1.4 });
  }
  // array bar
  var cellW = Math.min(64, (W - 80) / N), cellH = 46, total = N * cellW, sx = (W - total) / 2, ay = 40;
  draw.text('A').attr({ x: sx - 22, y: ay + cellH / 2, 'font-size': 20, 'font-style': 'italic', 'font-family': 'serif', fill: '#222' });
  for (i = 1; i <= N; i++) {
    var cx = sx + (i - 1) * cellW;
    cellRect[i] = gArray.rect(cellW, cellH).attr({ x: cx, y: ay, fill: '#ececec', stroke: '#555', 'stroke-width': 1 });
    gArray.text(String(i)).attr({ x: cx + cellW / 2, y: ay - 6, 'text-anchor': 'middle', 'font-size': 11, fill: '#666' });
    cellVal[i] = gArray.text(String(arr[i - 1])).attr({ x: cx + cellW / 2, y: ay + cellH / 2, 'text-anchor': 'middle', 'dominant-baseline': 'central', 'font-size': 16, 'font-family': 'sans-serif', fill: '#111' });
  }
  // nodes
  for (i = 1; i <= N; i++) {
    nodeCirc[i] = gNodes.circle(2 * R).attr({ cx: nodeX[i], cy: nodeY[i], fill: '#ececec', stroke: '#333', 'stroke-width': 1.4 });
    nodeIdx[i] = gNodes.text(String(i)).attr({ x: nodeX[i], y: nodeY[i] - R - 5, 'text-anchor': 'middle', 'font-size': 13, fill: '#333' });
    nodeVal[i] = gNodes.text(String(arr[i - 1])).attr({ x: nodeX[i], y: nodeY[i], 'text-anchor': 'middle', 'dominant-baseline': 'central', 'font-size': 17, 'font-weight': 'bold', 'font-family': 'sans-serif', fill: '#111' });
  }
