function arrowLine(a, b) {
  var dx = nodeX[b] - nodeX[a], dy = nodeY[b] - nodeY[a], len = Math.hypot(dx, dy) || 1, ux = dx / len, uy = dy / len;
  var x1 = nodeX[a] + ux * (R + 1), y1 = nodeY[a] + uy * (R + 1), x2 = nodeX[b] - ux * (R + 5), y2 = nodeY[b] - uy * (R + 5);
  gOver.line(x1, y1, x2, y2).stroke({ color: '#c0392b', width: 2 }).attr({ 'marker-end': 'url(#arrHead)' });
}

function drawFrame(idx) {
  if (!frames.length) return;
  idx = Math.max(0, Math.min(frames.length - 1, idx));
  frameIdx = idx;
  var f = frames[idx];
  gOver.clear();
  for (var i = 1; i <= N; i++) {
    var v = f.state[i];
    nodeVal[i].text(String(v));
    cellVal[i].text(String(v));
    nodeCirc[i].attr({ fill: (i === f.currentI) ? '#8a8a8a' : '#ececec' });
    nodeVal[i].attr({ fill: (i === f.currentI) ? '#fff' : '#111' });
  }
  // comparison arrows
  if (f.arrows) for (var k = 0; k < f.arrows.length; k++) arrowLine(f.arrows[k][0], f.arrows[k][1]);
  // italic i label
  if (f.currentI) gOver.text('i').attr({ x: nodeX[f.currentI] - R - 13, y: nodeY[f.currentI], 'font-size': 17, 'font-style': 'italic', 'font-family': 'serif', fill: '#111', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  // touched-index rings
  if (f.indices) for (k = 0; k < f.indices.length; k++) {
    var ti = f.indices[k]; if (ti >= 1 && ti <= N) gOver.circle(2 * (R + 5)).attr({ cx: nodeX[ti], cy: nodeY[ti], fill: 'none', stroke: '#e67e22', 'stroke-width': 2.5 });
  }
  // wrong-answer highlight on last frame
  if (runStatus === 'wrong' && idx === frames.length - 1) {
    for (k = 0; k < violations.length; k++) { var vi = violations[k]; gOver.circle(2 * (R + 8)).attr({ cx: nodeX[vi], cy: nodeY[vi], fill: 'none', stroke: '#c0392b', 'stroke-width': 3 }); }
  }
  capText.text(f.message || '');
  document.getElementById('pbCount').textContent = (idx + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message || '';
  var log = '';
  for (k = 0; k <= idx; k++) log += (k + 1) + '. ' + (frames[k].message || '') + '\n';
  document.getElementById('frameLog').textContent = log;
  document.getElementById('frameLog').scrollTop = document.getElementById('frameLog').scrollHeight;
}

