function trigger_runBuildMaxHeap() { runPipeline({}); }

function runPipeline(opts) {
  opts = opts || {};
  stopPlay();
  var arr = parseArray();
  document.getElementById('maxHeapifyCodeInput').value = arr.join(', ');
  buildStructure(arr);
  frames = [initFrameFor(arr)]; frameIdx = 0; violations = [];
  setStatus('running'); drawFrame(0);
  var code = document.getElementById('maxHeapifyCodeCode').value;
  var blob = new Blob([workerSource()], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var done = false;
  var timer = setTimeout(function () { if (!done) { done = true; worker.terminate(); URL.revokeObjectURL(url); frames = [initFrameFor(arr)]; setStatus('timeout'); drawFrame(0); } }, 2500);
  worker.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url);
    var d = e.data;
    var init = initFrameFor(arr);
    if (d.status === 'ok') {
      frames = [init].concat(d.frames || []);
      violations = d.violations || [];
      setStatus(violations.length ? 'wrong' : 'correct');
    } else {
      frames = [init].concat(d.frames || []);
      frames.push({ kind: 'err', state: frames[frames.length - 1].state.slice(), indices: [], currentI: null, arrows: [], message: '⚠ ' + (d.status === 'error' ? d.error : d.status) });
      setStatus('error');
    }
    if (opts.jumpEnd) drawFrame(frames.length - 1); else drawFrame(0);
  };
  worker.onerror = function (ev) { if (done) return; done = true; clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url); setStatus('error'); frames = [initFrameFor(arr)]; frames.push({ kind: 'err', state: frames[0].state.slice(), indices: [], currentI: null, arrows: [], message: '⚠ ' + (ev.message || 'worker error') }); drawFrame(frames.length - 1); };
  worker.postMessage({ code: code, array: arr, entry: 'maxHeapify' });
}

