    "function P(toks){this.toks=toks;this.i=0;}",
    "function parseExprSeq(toks){var p=new P(toks);var r=pOr(p);return r;}",
    "function pOr(p){var l=pAnd(p);while(p.peekName('or')){p.i++;var r=pAnd(p);l={t:'or',l:l,r:r};}return l;}",
    "function pAnd(p){var l=pNot(p);while(p.peekName('and')){p.i++;var r=pNot(p);l={t:'and',l:l,r:r};}return l;}",
