    "function pArith(p){var l=pTerm(p);while(p.peekOp(['+','-'])){var op=p.toks[p.i].v;p.i++;var r=pTerm(p);l={t:'bin',op:op,l:l,r:r};}return l;}",
    "function pTerm(p){var l=pFact(p);while(p.peekOp(['*','/','//','%'])){var op=p.toks[p.i].v;p.i++;var r=pFact(p);l={t:'bin',op:op,l:l,r:r};}return l;}",
