    " if(tk.t==='op'&&tk.v==='('){p.i++;var e2=pOr(p);p.expectOp(')');return e2;}",
    " throw new Error('unexpected token '+tk.v);}",
    "P.prototype.peekOp=function(set){var tk=this.toks[this.i];return tk&&tk.t==='op'&&set.indexOf(tk.v)>=0;};",
    "P.prototype.peekName=function(n){var tk=this.toks[this.i];return tk&&tk.t==='name'&&tk.v===n;};",
    "P.prototype.expectOp=function(o){if(!this.peekOp([o]))throw new Error('expected '+o);this.i++;};",
    "// ---- interpreter ----",
    "function truthy(v){return !(v===0||v===false||v===null||v===undefined);}",
    "function lookup(env,n){var e=env;while(e){if(n in e.vars)return e.vars[n];e=e.parent;}if(n in globalEnv.vars)return globalEnv.vars[n];throw new Error('undefined variable '+n);}",
    "function evalExpr(nd,env){switch(nd.t){case 'num':return nd.v;case 'var':return lookup(env,nd.name);",
    " case 'un':{var ev=evalExpr(nd.e,env);return nd.op==='-'?-ev:ev;}",
    " case 'bin':{var a=evalExpr(nd.l,env),b=evalExpr(nd.r,env);switch(nd.op){case '+':return a+b;case '-':return a-b;case '*':return a*b;case '/':return a/b;case '//':return Math.floor(a/b);case '%':return ((a%b)+b)%b;}throw new Error('bad op');}",
    " case 'cmp':{var ca=evalExpr(nd.l,env),cb=evalExpr(nd.r,env);switch(nd.op){case '<=':return ca<=cb;case '>=':return ca>=cb;case '==':return ca===cb;case '!=':return ca!==cb;case '<':return ca<cb;case '>':return ca>cb;}}",
    " case 'and':{var la=evalExpr(nd.l,env);if(!truthy(la))return la;return evalExpr(nd.r,env);}",
    " case 'or':{var lo=evalExpr(nd.l,env);if(truthy(lo))return lo;return evalExpr(nd.r,env);}",
    " case 'not':return truthy(evalExpr(nd.e,env))?0:1;",
    " case 'call':return callFunc(nd.name,nd.args.map(function(x){return evalExpr(x,env);}),env);}",
    " throw new Error('bad expr');}",
    "function callFunc(name,args,env){if(hostAPI[name])return hostAPI[name].apply(null,args);",
    " var fn=funcs[name];if(!fn)throw new Error('unknown function '+name);",
    " callDepth++;if(callDepth>DEPTH_CAP)throw new Error('recursion depth exceeded');",
    " var ne={vars:{},parent:globalEnv};for(var i=0;i<fn.params.length;i++)ne.vars[fn.params[i]]=args[i];",
    " var isE=(name===ENTRY);if(isE){ciStack.push(args[0]);currentI=args[0];}",
    " var ret=null;try{evalBlock(fn.body,ne);}catch(err){if(err&&err.__ret!==undefined){ret=err.__ret;}else{if(isE){ciStack.pop();currentI=ciStack.length?ciStack[ciStack.length-1]:null;}callDepth--;throw err;}}",
    " if(isE){ciStack.pop();currentI=ciStack.length?ciStack[ciStack.length-1]:null;}callDepth--;return ret;}",
    "function evalBlock(st,env){for(var i=0;i<st.length;i++)evalStmt(st[i],env);}",
    "function evalStmt(s,env){switch(s.type){case 'def':return;case 'pass':return;",
    " case 'assign':env.vars[s.name]=evalExpr(s.expr,env);return;",
    " case 'expr':evalExpr(s.expr,env);return;",
    " case 'return':throw {__ret:(s.expr?evalExpr(s.expr,env):null)};",
    " case 'if':{for(var b=0;b<s.branches.length;b++){if(truthy(evalExpr(s.branches[b].cond,env))){evalBlock(s.branches[b].body,env);return;}}if(s.elseB)evalBlock(s.elseB,env);return;}",
    " case 'while':{var g=0;while(truthy(evalExpr(s.cond,env))){chk();if(++g>OP_CAP)throw new Error('loop cap');evalBlock(s.body,env);}return;}}}",
    "// ---- driver ----",
    "function run(data){ARR=[null].concat(data.array);N=data.array.length;ENTRY=data.entry;FRAMES=[];opCount=0;callDepth=0;funcs={};globalEnv={vars:{}};ciStack=[];currentI=null;",
    " var raw=data.code.split('\\n');LINES=[];for(var i=0;i<raw.length;i++){var line=raw[i];var ind=0;while(ind<line.length&&(line[ind]===' '||line[ind]==='\\t')){ind+=line[ind]==='\\t'?4:1;ind= line[ind-1]==='\\t'?ind:ind;} ",
    "  var lead=0,sp=0;for(var c=0;c<line.length;c++){if(line[c]===' ')sp++;else if(line[c]==='\\t')sp+=4;else break;} lead=sp;",
