    " currentI=null;",
    " var viol=[];for(var p=1;p<=Math.floor(N/2);p++){if(2*p<=N&&ARR[p]<ARR[2*p])viol.push(p);if(2*p+1<=N&&ARR[p]<ARR[2*p+1])viol.push(p);}",
    " post({status:'ok',frames:FRAMES,final:ARR.slice(1),violations:viol});}",
