}

function trigger_runBuildMaxHeap() { runPipeline({}); }

function runPipeline(opts) {
  opts = opts || {};
  stopPlay();
  var arr = parseArray();
  document.getElementById('maxHeapifyCodeInput').value = arr.join(', ');
  buildStructure(arr);
  frames = [initFrameFor(arr)]; frameIdx = 0; violations = [];
  setStatus('running'); drawFrame(0);
  var code = document.getElementById('maxHeapifyCodeCode').value;
  var blob = new Blob([workerSource()], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var done = false;
  var timer = setTimeout(function () { if (!done) { done = true; worker.terminate(); URL.revokeObjectURL(url); frames = [initFrameFor(arr)]; setStatus('timeout'); drawFrame(0); } }, 2500);
  worker.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url);
    var d = e.data;
    var init = initFrameFor(arr);
    if (d.status === 'ok') {
      frames = [init].concat(d.frames || []);
      violations = d.violations || [];
      setStatus(violations.length ? 'wrong' : 'correct');
    } else {
      frames = [init].concat(d.frames || []);
      frames.push({ kind: 'err', state: frames[frames.length - 1].state.slice(), indices: [], currentI: null, arrows: [], message: '⚠ ' + (d.status === 'error' ? d.error : d.status) });
      setStatus('error');
    }
    if (opts.jumpEnd) drawFrame(frames.length - 1); else drawFrame(0);
  };
  worker.onerror = function (ev) { if (done) return; done = true; clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url); setStatus('error'); frames = [initFrameFor(arr)]; frames.push({ kind: 'err', state: frames[0].state.slice(), indices: [], currentI: null, arrows: [], message: '⚠ ' + (ev.message || 'worker error') }); drawFrame(frames.length - 1); };
  worker.postMessage({ code: code, array: arr, entry: 'maxHeapify' });
}

// ---------- playback ----------
function update_speed(v) { speed = v; if (playing) { stopPlay(); startPlay(); } }
function startPlay() { playing = true; document.getElementById('pbPlayBtn').textContent = '⏸'; var iv = 1100 - speed * 100; playTimer = setInterval(function () { if (frameIdx < frames.length - 1) drawFrame(frameIdx + 1); else stopPlay(); }, iv); }
function stopPlay() { playing = false; document.getElementById('pbPlayBtn').textContent = '▶'; if (playTimer) { clearInterval(playTimer); playTimer = null; } }
function pbPlay() { if (playing) stopPlay(); else { if (frameIdx >= frames.length - 1) drawFrame(0); startPlay(); } }
function pbFirst() { stopPlay(); drawFrame(0); }
function pbPrev() { stopPlay(); drawFrame(frameIdx - 1); }
function pbNext() { stopPlay(); drawFrame(frameIdx + 1); }

// ---------- code tabs ----------
var SAMPLE = "def maxHeapify(i, heapSize):\n    l = left(i)\n    r = right(i)\n    largest = i\n    if l <= heapSize and value(l) > value(largest):\n        largest = l\n    if r <= heapSize and value(r) > value(largest):\n        largest = r\n    if largest != i:\n        swap(i, largest)\n        maxHeapify(largest, heapSize)\n";
var BUGGY = "def maxHeapify(i, heapSize):\n    l = left(i)\n    r = right(i)\n    largest = i\n    if l <= heapSize and value(l) > value(largest):\n        largest = l\n    if r <= heapSize and value(r) > value(largest):\n        largest = r\n    if largest != i:\n        swap(i, largest)\n        # BUG: missing the recursive call, so a swapped-down value is never re-checked\n";
var STARTER = "def maxHeapify(i, heapSize):\n    # your code here\n    pass\n";
function loadTab(which) {
  var ta = document.getElementById('maxHeapifyCodeCode');
  ta.value = which === 'sample' ? SAMPLE : which === 'buggy' ? BUGGY : STARTER;
  document.getElementById('tabSample').className = which === 'sample' ? 'active' : '';
  document.getElementById('tabBuggy').className = which === 'buggy' ? 'active' : '';
  document.getElementById('tabStarter').className = which === 'starter' ? 'active' : '';
}

// ---------- demo steps ----------
var STEPS = [
  { t: 'The starting array as a tree', n: 'The 10-element array is drawn as a complete binary tree in heap order; nothing is a heap yet. BUILD-MAX-HEAP will call your maxHeapify starting at the last internal node, index floor(10/2) = 5, and work upward to the root.' },
  { t: 'Run the correct MAX-HEAPIFY bottom-up', n: 'With the correct recursive implementation, pressing run shades each i in dark gray, draws comparison arrows to its children, and swaps values downward until every subtree is a heap — ending in the max-heap with 16 at the root (panel f).' },
  { t: 'Watch a near-miss diverge', n: 'Replace the body with the buggy version that swaps once but never recurses. Re-run: the value pushed down at the root is never re-checked against its new children, so the final tree violates the max-heap property — the replay shows exactly where and why it breaks.' }
];
var stepIdx = 0;
function applyStep(k) {
  stepIdx = k;
  document.getElementById('stepLabel').textContent = (k + 1) + '/' + STEPS.length;
  document.getElementById('demoNarration').textContent = STEPS[k].t + ' — ' + STEPS[k].n;
  document.getElementById('maxHeapifyCodeInput').value = '4, 1, 3, 2, 16, 9, 10, 14, 8, 7';
  if (k === 0) { loadTab('sample'); buildStructure(parseArray()); frames = [initFrameFor(parseArray())]; violations = []; setStatus('not-run'); drawFrame(0); }
  else if (k === 1) { loadTab('sample'); runPipeline({ jumpEnd: true }); }
  else { loadTab('buggy'); buildStructure(parseArray()); frames = [initFrameFor(parseArray())]; violations = []; setStatus('not-run'); drawFrame(0); }
}
function nextStep() { applyStep(Math.min(STEPS.length - 1, stepIdx + 1)); }
function prevStep() { applyStep(Math.max(0, stepIdx - 1)); }

// ---------- init ----------
loadTab('sample');
buildStructure(parseArray());
frames = [initFrameFor(parseArray())];
drawFrame(0);
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

