    nodeVal[i].attr({ fill: (i === f.currentI) ? '#fff' : '#111' });
  }
  if (f.arrows) for (var k = 0; k < f.arrows.length; k++) arrowLine(f.arrows[k][0], f.arrows[k][1]);
