    for (k = 0; k < violations.length; k++) { var vi = violations[k]; gOver.circle(2 * (R + 8)).attr({ cx: nodeX[vi], cy: nodeY[vi], fill: 'none', stroke: '#c0392b', 'stroke-width': 3 }); }
  }
